/** The complete registry; IDs and question IDs are stable for local saved retakes. */
export const assessments = [
  marketingAssessment,
  marketingReadiness, customerInsight, analyticsData, aiAdoption,
  changeReadiness, customerAdoption, organizationalReadiness, strategicMarketing,
  financialMarketing, sustainabilityResilience, agencyTrust, personalChange,
];

/** Return undefined for an unknown route so the UI can present a safe fallback. */
export function getAssessment(id) {
  return assessments.find(item => item.id === id);
}
